(() => {
  const names = [...document.querySelectorAll('[data-memory-note] button')].map((b) => b.getAttribute('aria-label'));
  const notes = document.querySelector('[data-memory-note]').parentElement;
  const box = document.createElement('div');
  box.setAttribute('data-capture-overlay', '');
  box.style.cssText = 'margin:18px 8px 0;padding:12px 14px;border-radius:12px;border:1px dashed color-mix(in srgb, var(--color-ink) 30%, transparent);font:12px/18px ui-monospace,Menlo,monospace;color:var(--color-ink)';
  box.innerHTML = '<div style="opacity:.6;margin-bottom:6px">Capture overlay: the Forget buttons as a screen reader names them</div>' + names.map((n) => '<div>button: ' + n.replace(/&/g,'&amp;').replace(/</g,'&lt;') + '</div>').join('');
  notes.after(box);
  return names;
})()
